!function(){if(!("serviceWorker"in navigator))return;const k="wb-sw-refresh-20261001-1";navigator.serviceWorker.addEventListener("controllerchange",()=>{if(sessionStorage.getItem(k)!=="1"){sessionStorage.setItem(k,"1");location.reload()}});window.addEventListener("load",()=>{navigator.serviceWorker.register("/sw.js",{updateViaCache:"none"}).then(e=>e.update()).catch(()=>{})});let p=null;window.addEventListener("beforeinstallprompt",e=>{e.preventDefault();p=e;window.woongbiInstallApp=async()=>{if(!p)return!1;p.prompt();const r=await p.userChoice;p=null;return"accepted"===r.outcome}});window.addEventListener("appinstalled",()=>{p=null;window.dispatchEvent(new CustomEvent("woongbi:pwa-installed"))})}();
